def copy_single_images(apps, schema_editor):
    """Each listing's single image becomes its cover photo, with WebP thumbnails.

    The original file is reused in place (no copy). If a file is missing from storage the
    photo is still created and the API falls back to the original URL.
    """
    from pathlib import Path

    from django.core.files.base import ContentFile

    from rental.services.photos import THUMBNAIL_WIDTHS, render_webp

    Vehicle = apps.get_model("rental", "Vehicle")
    VehiclePhoto = apps.get_model("rental", "VehiclePhoto")
    alias = schema_editor.connection.alias
    for vehicle in Vehicle.objects.using(alias).exclude(vehicle_image="").iterator():
        photo = VehiclePhoto.objects.using(alias).create(vehicle=vehicle, image=vehicle.vehicle_image.name,
                                                         order=0, is_cover=True)
        try:
            for field, width in THUMBNAIL_WIDTHS.items():
                with photo.image.open("rb") as source:
                    data = render_webp(source, width)
                name = f"{Path(photo.image.name).stem}-{width}.webp"
                getattr(photo, field).save(name, ContentFile(data), save=False)
        except (OSError, ValueError):
            continue
        photo.save(using=alias)


def restore_single_images(apps, schema_editor):
    Vehicle = apps.get_model("rental", "Vehicle")
    VehiclePhoto = apps.get_model("rental", "VehiclePhoto")
    for photo in VehiclePhoto.objects.using(schema_editor.connection.alias).order_by("-is_cover", "order"):
        Vehicle.objects.filter(pk=photo.vehicle_id, vehicle_image="").update(vehicle_image=photo.image.name)


